const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const head=(eyebrow,title,sub,actions='')=>`<header class="screen-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="screen-subtitle">${sub}</p></div><div class="head-actions">${actions}</div></header>`;
const progress=(v,cl='')=>`<div class="progress-track ${cl}"><span style="width:${v}%"></span></div>`;
const stat=(label,value,note,icon)=>`<article class="kpi"><div class="kpi-label">${icon||''}${label}</div><div class="kpi-value">${value}</div><div class="kpi-note">${note}</div></article>`;
function transact(ctx,amount,label){if(ctx.state.balance+amount<0){ctx.toast('Недостаточно средств для этой операции.');return false}ctx.setState({balance:Math.round((ctx.state.balance+amount)*100)/100,ledger:[{label,amount,date:ctx.state.date},...(ctx.state.ledger||[])]});return true}
function close(ctx){ctx.closeModal?.();if(!ctx.closeModal)document.querySelector('[data-modal-close]')?.click()}
function bars(values,color='#a44b5c'){return `<svg viewBox="0 0 530 170" class="chart-svg" role="img" aria-label="Расходы по месяцам, в миллионах евро"><g stroke="#29313c" stroke-width=".6"><path d="M35 20H520M35 65H520M35 110H520M35 145H520"/></g><g fill="#6e7a89" font-size="10"><text x="5" y="24">12</text><text x="10" y="69">8</text><text x="10" y="114">4</text></g>${values.map((v,i)=>`<rect x="${55+i*77}" y="${145-v*9.5}" width="33" height="${v*9.5}" rx="2" fill="${i===4?'#ca6577':color}"/><text x="${72+i*77}" y="${137-v*9.5}" text-anchor="middle" font-size="10" fill="#b7bfcb">${String(v).replace('.',',')}</text><text x="${72+i*77}" y="164" text-anchor="middle" font-size="10" fill="#778291">${['ЯНВ','ФЕВ','МАР','АПР','МАЙ','ИЮН'][i]}</text>`).join('')}</svg>`}
function radar(){return `<svg viewBox="0 0 360 240" role="img" aria-label="Характеристики болида: аэродинамика 83, мощность 88, надёжность 86, шины 79, охлаждение 81" class="management-radar"><g fill="none" stroke="#333c48">${[1,.75,.5,.25].map(s=>{const pts=Array.from({length:5},(_,i)=>[180+86*s*Math.sin(i*2*Math.PI/5),116-86*s*Math.cos(i*2*Math.PI/5)].join(',')).join(' ');return `<polygon points="${pts}"/>`}).join('')}${Array.from({length:5},(_,i)=>`<path d="M180 116L${180+86*Math.sin(i*2*Math.PI/5)} ${116-86*Math.cos(i*2*Math.PI/5)}"/>`).join('')}</g><polygon points="180,43 250,93 220,171 143,167 110,94" fill="#c83b4d25" stroke="#c56375" stroke-width="2"/><polygon points="180,53 243,96 217,167 141,170 119,96" fill="none" stroke="#a2adb8" stroke-dasharray="4 4" opacity=".7"/><g fill="#aab3c0" font-size="11" text-anchor="middle"><text x="180" y="15">Аэродинамика · 83</text><text x="295" y="92">Мощность · 88</text><text x="267" y="216">Надёжность · 86</text><text x="95" y="216">Шины · 79</text><text x="58" y="92">Охлаждение · 81</text></g></svg>`}
export function mountDevelopment(container,ctx){const {state,icon}=ctx;const render=()=>{const projects=state.projects;const active=projects.filter(p=>p.progress<100);container.innerHTML=`<div class="screen management-screen">${head('ТЕХНИЧЕСКИЙ ЦЕНТР / V28','Разработка','От первого расчёта до преимущества на трассе.',`<button class="btn" id="engineer-allocation">${icon('users',15)} Инженеры</button><button class="btn btn-primary" id="new-project">${icon('plus',15)} Новый проект</button>`)}<div class="kpi-grid">${stat('Текущие проекты',String(active.length).padStart(2,'0'),'В работе · '+projects.filter(p=>p.progress>=100).length+' завершено',icon('layers',15))}${stat('Инженерный состав',(state.engineering?Object.values(state.engineering).reduce((a,b)=>a+b,0):56)+' <span class="dim" style="font-size:14px">/ 60</span>','Опыт команды · 86/100',icon('users',15))}${stat('Бюджет разработок','€12,8 млн','План на сезон · €24,0 млн',icon('wallet',15))}${stat('Темп развития','+0,42 с','Прогресс с начала сезона',icon('trending-up',15))}</div><div class="management-dev-layout"><div><div class="management-section-label"><h2>Программа модернизации</h2><span class="muted">${projects.length} проекта</span></div><div class="management-projects">${projects.map((p,i)=>`<article class="panel management-project"><div class="management-project-icon">${icon(p.category==='Надёжность'?'shield-check':p.category==='Инфраструктура'?'building-2':'drafting-compass',25)}</div><div class="management-project-info"><div class="management-project-heading"><div><span class="eyebrow">${esc(p.category)}</span><h2>${esc(p.name)}</h2></div><span class="chip ${p.installed?'green':p.progress>=100?'amber':''}">${p.installed?'Установлено':p.progress>=100?'Готово':p.progress+'%'}</span></div><p>${p.category==='Инфраструктура'?'Расширение возможностей технического центра.':p.id==='floor-b'?'Перераспределение воздушного потока под днищем.':p.category==='Аэродинамика'?'Улучшение баланса и сцепления в поворотах.':p.category==='Трансмиссия'?'Снижение потерь и ускорение переключений.':'Контроль температур и стабильность компонентов.'}</p>${progress(p.progress,p.installed?'green':'')}<div class="management-project-details"><span>${icon('users',13)} ${p.engineers} инженеров</span><span>${icon('clock-3',13)} ${p.days>0?p.days+' дн.':'Завершено'}</span><strong>${esc(p.gain)}</strong></div><div class="management-project-bottom"><span class="muted">Ответственная: Е. Морозова</span><button class="btn btn-sm ${p.progress>=100&&!p.installed?'btn-primary':''}" data-project="${p.id}">${p.progress>=100&&!p.installed?(p.category==='Инфраструктура'?'Завершить':'Установить'):'Подробности'}</button></div></div></article>`).join('')}</div></div><aside><section class="panel"><header class="panel-head"><h2>Баланс характеристик V28</h2><span class="chip">83</span></header><div class="management-radar-wrap">${radar()}<div class="chart-legend"><span>Наш болид</span><span style="--legend-color:#9aa7b6">Среднее по серии</span></div></div></section><section class="panel management-advisor"><div class="management-advisor-head"><img src="assets/morozova.webp" alt="Елена Морозова"><div><strong>Елена Морозова</strong><small>Технический директор · 91</small></div></div><blockquote>«Мы уступаем в медленных поворотах. Переднее крыло даст больше, чем очередная прибавка мощности».</blockquote><span class="chip amber">Перфекционист</span><p>+6% к качеству · +10% к срокам</p></section><section class="panel"><header class="panel-head"><h2>Ближайшая веха</h2>${icon('flag',16)}</header><div class="panel-body"><strong>Гран-при Лазурного берега</strong><p class="muted" style="font-size:12px;margin:9px 0 16px">Днище B будет готово к квалификации. Установка доступна после завершения испытаний.</p><button class="btn btn-full" data-route="calendar">Посмотреть календарь</button></div></section></aside></div></div>`;container.querySelector('#new-project').onclick=()=>newProject();container.querySelector('#engineer-allocation').onclick=()=>allocation();container.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>projectDetail(b.dataset.project))};function newProject(){ctx.modal({title:'Новый инженерный проект',body:`<p class="muted">Выберите направление. Стоимость будет списана из доступного бюджета.</p><div class="field" style="margin-top:18px"><label for="project-kind">Проект</label><select id="project-kind"><option value="wing">Переднее крыло C · €1,8 млн · 14 дней</option><option value="gear">Коробка GT8 Evo · €2,4 млн · 21 день</option><option value="battery">Накопитель энергии · €1,3 млн · 12 дней</option></select></div><div class="field"><label for="project-focus">Приоритет</label><select id="project-focus"><option value="balanced">Сбалансированный</option><option value="performance">Максимальная эффективность · +€0,4 млн</option><option value="speed">Ускоренная разработка · −4 дня, +€0,6 млн</option></select></div><div class="management-modal-stats"><span>Доступно<strong>${ctx.money(state.balance)}</strong></span><span>Руководитель<strong>Е. Морозова · 91</strong></span></div>`,footer:'<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" id="start-project">Начать разработку</button>',onMount:el=>{el.querySelector('#start-project').onclick=()=>{const k=el.querySelector('#project-kind').value,f=el.querySelector('#project-focus').value;const cfg={wing:['Переднее крыло C',1.8,14,'Аэродинамика','+0,12 с / круг'],gear:['Коробка GT8 Evo',2.4,21,'Трансмиссия','+4 эффективности'],battery:['Накопитель энергии',1.3,12,'Силовая установка','+5 рекуперации']}[k];if(state.projects.some(p=>p.name===cfg[0]&&!p.installed)){ctx.toast('Этот проект уже есть в программе разработки.');return}const cost=cfg[1]+(f==='speed'?.6:f==='performance'?.4:0);if(!transact(ctx,-cost,cfg[0]))return;ctx.setState({projects:[...state.projects,{id:k+'-'+Date.now(),name:cfg[0],category:cfg[3],progress:0,days:cfg[2]-(f==='speed'?4:0),engineers:12,gain:cfg[4],cost,focus:f}]});close(ctx);render();ctx.toast(cfg[0]+': проект запущен.')}}})}function allocation(){const a=state.engineering||{aero:24,power:18,reliability:14};ctx.modal({title:'Распределение инженеров',body:`<p class="muted">Доступно 60 специалистов. Назначения сохраняются для следующих проектов.</p>${[['aero','Аэродинамика'],['power','Силовая установка'],['reliability','Надёжность']].map(([k,l])=>`<div class="field" style="margin-top:15px"><label for="eng-${k}">${l} <b id="out-${k}">${a[k]}</b></label><input type="range" id="eng-${k}" min="0" max="40" value="${a[k]}"></div>`).join('')}<p id="eng-total" class="muted"></p>`,footer:'<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" id="save-engineers">Сохранить</button>',onMount:el=>{const upd=()=>{let sum=0;for(const k of ['aero','power','reliability']){const n=+el.querySelector('#eng-'+k).value;sum+=n;el.querySelector('#out-'+k).textContent=n}el.querySelector('#eng-total').textContent='Назначено '+sum+' из 60';el.querySelector('#save-engineers').disabled=sum>60};el.querySelectorAll('input').forEach(i=>i.oninput=upd);upd();el.querySelector('#save-engineers').onclick=()=>{const val={};['aero','power','reliability'].forEach(k=>val[k]=+el.querySelector('#eng-'+k).value);ctx.setState({engineering:val});close(ctx);ctx.toast('Распределение инженеров сохранено.')}}})}function projectDetail(id){const p=state.projects.find(p=>p.id===id);if(p.progress>=100&&!p.installed){const infrastructure=p.category==='Инфраструктура';ctx.setState({projects:state.projects.map(x=>x.id===id?{...x,installed:true}:x),...(infrastructure?{facilityLevels:{...state.facilityLevels,[id.replace('facility-','')]:((state.facilityLevels||{})[id.replace('facility-','')]||({simulator:3,tunnel:4,factory:3,academy:2}[id.replace('facility-','')]||2))+1}}:{})});render();ctx.toast(p.name+(infrastructure?': модернизация завершена.':': установлен на оба болида.'));return}ctx.modal({title:p.name,body:`<div class="management-modal-stats"><span>Готовность<strong>${p.progress}%</strong></span><span>До завершения<strong>${p.days} дн.</strong></span><span>Стоимость<strong>${ctx.money(p.cost)}</strong></span><span>Ожидаемый эффект<strong>${p.gain}</strong></span></div><p class="muted" style="margin-top:18px">${p.installed?'Деталь установлена. Следующая разработка начнётся с её характеристик.':'Проект продвигается при переходе к следующему дню кнопкой «Продолжить». После 100% готовности деталь можно установить.'}</p>`,footer:'<button class="btn btn-primary" data-modal-close>Понятно</button>'})}render();return()=>{}}

const schedule=[{day:'2028-05-07',type:'race',title:'Гран-при Сакуры',series:'formula',status:'Завершён',detail:'Келлер — P4 · Вебер — P7. Команда заработала 18 очков.'},{day:'2028-05-13',type:'race',title:'GT · Побережье',series:'gt',status:'Завершён',detail:'VANTA GT завершила этап на 6-м месте.'},{day:'2028-05-18',type:'meeting',title:'Брифинг перед этапом',series:'formula',status:'Сегодня',detail:'Задача: попасть в первые восемь обеими машинами.'},{day:'2028-05-19',type:'practice',title:'Лазурный берег · Практика',series:'formula',status:'Предстоящий',detail:'11:00 — FP1. 16:00 — FP2. Сбор данных по деградации шин.'},{day:'2028-05-20',type:'development',title:'Днище B · Испытания',series:'formula',status:'Предстоящий',detail:'Финальная проверка надёжности и установка перед квалификацией.'},{day:'2028-05-20',type:'qualifying',title:'Лазурный берег · Квалификация',series:'formula',status:'Предстоящий',detail:'15:00 — квалификация. Ожидается сухая погода.'},{day:'2028-05-21',type:'race',title:'Гран-при Лазурного берега',series:'formula',status:'Предстоящий',detail:'Раунд 6/18 · 58 кругов · 14:00. Возможен кратковременный дождь.'},{day:'2028-05-25',type:'contract',title:'Переговоры с агентом Вебера',series:'formula',status:'Предстоящий',detail:'Обсуждение контракта на сезоны 2029–2030.'},{day:'2028-05-27',type:'race',title:'GT · Северное кольцо',series:'gt',status:'Предстоящий',detail:'Раунд 4/12 · две гонки по 60 минут.'},{day:'2028-05-28',type:'race',title:'6 часов Северного кольца',series:'endurance',status:'Предстоящий',detail:'Раунд 3/8 · смена экипажей, управление топливом и многоклассовый трафик.'},{day:'2028-06-04',type:'race',title:'Гран-при Альп',series:'formula',status:'Предстоящий',detail:'Раунд 7/18 · 62 круга.'},{day:'2028-06-11',type:'race',title:'GT · Альпийский парк',series:'gt',status:'Предстоящий',detail:'Раунд 5/12 · спринтерский уик-энд.'},{day:'2028-06-18',type:'race',title:'Гран-при Атлантики',series:'formula',status:'Предстоящий',detail:'Раунд 8/18 · 55 кругов.'}];
export function mountCalendar(container,ctx){let month=4,year=2028,filter='all',selected='2028-05-21',view='month';const {icon}=ctx;const render=()=>{const first=new Date(Date.UTC(year,month,1)),offset=(first.getUTCDay()+6)%7,days=new Date(Date.UTC(year,month+1,0)).getUTCDate();const filtered=schedule.filter(e=>filter==='all'||e.series===filter);const inMonth=filtered.filter(e=>e.day.startsWith(year+'-'+String(month+1).padStart(2,'0')));const detail=filtered.filter(e=>e.day===selected);const dayKey=d=>`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;container.innerHTML=`<div class="screen management-screen">${head('СЕЗОН 2028 / ПЛАНИРОВАНИЕ','Календарь','Гоночные уик-энды, разработки и решения в одном расписании.',`<div class="segmented"><button data-calview="month" class="${view==='month'?'active':''}">${icon('calendar-days',14)} Месяц</button><button data-calview="list" class="${view==='list'?'active':''}">${icon('list',14)} Список</button></div>`)}<div class="management-calendar-toolbar"><div class="management-month"><button class="icon-btn" id="prev-month" aria-label="Предыдущий месяц">${icon('chevron-left',20)}</button><h2>${first.toLocaleDateString('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'}).replace(' г.','')}</h2><button class="icon-btn" id="next-month" aria-label="Следующий месяц">${icon('chevron-right',20)}</button><button class="btn btn-sm" id="today-month">Текущий месяц</button></div><select id="calendar-filter" aria-label="Дисциплина в календаре"><option value="all">Все программы</option><option value="formula">Formula World</option><option value="gt">GT World Series</option><option value="endurance">Endurance Cup</option></select></div><div class="management-calendar-layout"><section class="panel">${view==='month'?`<div class="management-weekdays">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(d=>`<span>${d}</span>`).join('')}</div><div class="management-calendar-grid">${Array.from({length:offset},()=>'<div class="management-calendar-empty"></div>').join('')}${Array.from({length:days},(_,i)=>{const key=dayKey(i+1),events=inMonth.filter(e=>e.day===key);return `<button class="management-calendar-day ${key===ctx.state.date?'today':''} ${key===selected?'selected':''}" data-day="${key}" aria-label="${i+1} ${first.toLocaleDateString('ru-RU',{month:'long'})}, событий ${events.length}"><span>${i+1}</span>${events.map(e=>`<i class="management-cal-event ${e.type}">${esc(e.title)}</i>`).join('')}</button>`}).join('')}</div>`:`<div class="management-calendar-list">${inMonth.length?inMonth.map(e=>`<button data-day="${e.day}" class="management-calendar-list-item ${e.day===selected?'selected':''}"><span class="management-date-tile"><b>${Number(e.day.slice(-2))}</b><small>${first.toLocaleDateString('ru-RU',{month:'short'})}</small></span><span><strong>${esc(e.title)}</strong><small>${e.series==='formula'?'FORMULA WORLD':e.series==='gt'?'GT WORLD SERIES':'ENDURANCE CUP'}</small></span><span class="chip">${e.status}</span></button>`).join(''):'<div class="empty-state">В этом месяце нет запланированных событий.</div>'}</div>`}</section><aside class="panel management-event-detail"><div class="management-event-top"><span class="eyebrow">${new Date(selected+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'long'})}</span><h2>${new Date(selected+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</h2></div>${detail.length?detail.map((e,eventIndex)=>`<article><span class="chip ${e.type==='race'?'red':''}">${e.type==='race'?'Гонка':e.type==='development'?'Разработка':'Событие'}</span><h3>${esc(e.title)}</h3><p>${esc(e.detail)}</p><button class="btn ${e.type==='race'?'btn-primary':''} btn-full" data-event-type="${e.type}" data-event-series="${e.series}" data-event-index="${eventIndex}">${e.type==='race'?'Открыть гоночный центр':e.type==='development'?'Открыть разработку':'Открыть подробности'}</button></article>`).join(''):'<div class="empty-state">Свободный день.<br>Можно заняться командой и разработками.</div>'}<div class="management-calendar-legend"><span><i style="background:#c76576"></i>Formula World</span><span><i style="background:#81a7bb"></i>GT World Series</span><span><i style="background:#c7a569"></i>Endurance Cup</span></div></aside></div></div>`;container.querySelector('#calendar-filter').value=filter;container.querySelector('#calendar-filter').onchange=e=>{filter=e.target.value;render()};container.querySelector('#prev-month').onclick=()=>{month--;if(month<0){month=11;year--}render()};container.querySelector('#next-month').onclick=()=>{month++;if(month>11){month=0;year++}render()};container.querySelector('#today-month').onclick=()=>{const d=new Date(ctx.state.date);month=d.getUTCMonth();year=d.getUTCFullYear();selected=ctx.state.date;render()};container.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{selected=b.dataset.day;render()});container.querySelectorAll('[data-calview]').forEach(b=>b.onclick=()=>{view=b.dataset.calview;render()});container.querySelectorAll('[data-event-type]').forEach(b=>b.onclick=()=>{if(b.dataset.eventType==='race'){ctx.setState({discipline:b.dataset.eventSeries});ctx.navigate('race')}else if(b.dataset.eventType==='development')ctx.navigate('development');else ctx.modal({title:detail[+b.dataset.eventIndex]?.title||'Событие',body:`<p>${detail[+b.dataset.eventIndex]?.detail}</p><p class="muted">Участники уведомлены. Событие отображается в календаре команды.</p>`,footer:'<button class="btn btn-primary" data-modal-close>Понятно</button>'})})};render();return()=>{}}

export function mountFinance(container,ctx){let tab='overview';const {state,icon}=ctx;const sponsors=[{name:'NORD',category:'Титульный партнёр',sum:7.2,zone:'Боковые понтоны',expires:'2029',color:'#c5d4df'},{name:'APEX Energy',category:'Энергетический партнёр',sum:4.8,zone:'Заднее антикрыло',expires:'2028',color:'#d7b86e'},{name:'IONIX',category:'Технологический партнёр',sum:3.6,zone:'Носовой обтекатель',expires:'2030',color:'#82b3b9'}];const render=()=>{if(state.sponsors.includes('HELIX')&&!sponsors.some(s=>s.name==='HELIX'))sponsors.push({name:'HELIX',category:'Технологии и аналитика',sum:2.4,zone:'Кожух двигателя',expires:'2029',color:'#bfa3c8'});container.innerHTML=`<div class="screen management-screen">${head('БИЗНЕС / VANTA GROUP','Финансы','Ресурсы команды. Сегодня и на дистанции сезона.',`<button class="btn" id="finance-export">${icon('download',15)} Выгрузить отчёт</button><button class="btn btn-primary" id="sponsor-offer">${icon('handshake',15)} Предложения партнёров</button>`)}<div class="kpi-grid">${stat('Доступные средства',ctx.money(state.balance),'Общий резерв VANTA Group',icon('wallet',15))}${stat('Бюджет сезона','€112 млн','Освоено 43% годового плана',icon('chart-no-axes-combined',15))}${stat('Спонсорские контракты',ctx.money(sponsors.reduce((sum,s)=>sum+s.sum,0)),sponsors.length+' действующих партнёра',icon('handshake',15))}${stat('Прогноз на конец года','€21,3 млн','При выполнении базового плана',icon('trending-up',15))}</div><div class="tabs management-tabs"><button class="tab ${tab==='overview'?'active':''}" data-ftab="overview">Обзор бюджета</button><button class="tab ${tab==='sponsors'?'active':''}" data-ftab="sponsors">Спонсоры и контракты</button><button class="tab ${tab==='ledger'?'active':''}" data-ftab="ledger">Все операции</button></div>${tab==='sponsors'?`<div class="management-sponsor-grid">${sponsors.map(s=>`<article class="panel management-sponsor"><div class="management-wordmark" style="color:${s.color}">${s.name}</div><span class="eyebrow">${s.category}</span><h2>${ctx.money(s.sum)}<small> / сезон</small></h2><dl><div><dt>Размещение</dt><dd>${s.zone}</dd></div><div><dt>Контракт</dt><dd>До конца ${s.expires}</dd></div><div><dt>Статус</dt><dd class="positive">Активен</dd></div></dl><button class="btn btn-full" data-sponsor="${s.name}">Условия контракта</button></article>`).join('')}</div><section class="panel management-sponsor-note"><div>${icon('paintbrush',22)}</div><div><h3>Раскраска — часть коммерческого контракта</h3><p>В гараже можно выбрать зону и размер логотипа. Требования партнёров показываются рядом с редактором.</p></div><button class="btn" data-route="garage">Открыть ливрею</button></section>`:tab==='ledger'?ledger():`<div class="management-finance-layout"><section class="panel"><header class="panel-head"><h2>Расходы по месяцам</h2><span class="chip">Млн € · 2028</span></header><div class="panel-body">${bars([7.2,8.8,8.1,10.4,9.2,8.6])}<div class="chart-legend" style="margin-top:20px"><span>Фактические расходы</span><span style="--legend-color:#a44b5c">Июнь: план</span></div></div></section><section class="panel"><header class="panel-head"><h2>Распределение бюджета</h2>${icon('chart-pie',16)}</header><div class="panel-body management-budget-breakdown">${[['Разработка и техника',42,47,'#c56173'],['Зарплаты',26,29.1,'#8595ab'],['Логистика',18,20.2,'#80a49a'],['База и операции',14,15.7,'#b69c71']].map(([l,p,s,c])=>`<div><div><span><i style="background:${c}"></i>${l}</span><strong>${p}%</strong></div><div class="progress-track"><span style="width:${p*2}%;background:${c}"></span></div><small>€${String(s).replace('.',',')} млн</small></div>`).join('')}</div></section></div>${ledger()}<section class="management-finance-callout">${icon('shield-check',23)}<div><strong>Финансовый план устойчив</strong><p>Текущего резерва хватает на запланированные обновления и операционные расходы. Бонусы за результаты в прогноз не включены.</p></div></section>`}</div>`;container.querySelectorAll('[data-ftab]').forEach(b=>b.onclick=()=>{tab=b.dataset.ftab;render()});container.querySelector('#sponsor-offer').onclick=offer;container.querySelector('#finance-export').onclick=()=>{const rows=[['Дата','Операция','Сумма EUR'],...allLedger().map(r=>[r.date,r.label,Math.round(r.amount*1000000)])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='APEX-finance-2028.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);ctx.toast('Финансовый отчёт выгружен.')};container.querySelectorAll('[data-sponsor]').forEach(b=>b.onclick=()=>{const s=sponsors.find(x=>x.name===b.dataset.sponsor);ctx.modal({title:s.name+' · контракт',body:`<div class="management-wordmark" style="color:${s.color};font-size:32px">${s.name}</div><div class="management-modal-stats"><span>Выплата за сезон<strong>${ctx.money(s.sum)}</strong></span><span>Срок<strong>До ${s.expires}</strong></span></div><p style="margin-top:20px">Обязательное размещение: ${s.zone.toLowerCase()}. Фирменный знак должен быть контрастным и полностью видимым.</p><div class="modal-callout">${s.name==='NORD'?'Бонус за подиум на следующем этапе: €250 000.':'Эксклюзивность в товарной категории. Отраслевые конкуренты не допускаются.'}</div>`,footer:'<button class="btn" data-modal-close>Закрыть</button><button class="btn btn-primary" id="sponsor-garage">Открыть гараж</button>',onMount:el=>el.querySelector('#sponsor-garage').onclick=()=>{close(ctx);ctx.navigate('garage')}})})};function allLedger(){return [...(state.ledger||[]),{date:'2028-05-17',label:'NORD · регулярный платёж',amount:.6},{date:'2028-05-16',label:'Зарплаты пилотов и персонала',amount:-1.2},{date:'2028-05-15',label:'Производство днища B',amount:-.34},{date:'2028-05-14',label:'Призовые · Гран-при Сакуры',amount:.85}]}function ledger(){return `<section class="panel management-ledger"><header class="panel-head"><h2>${tab==='ledger'?'История операций':'Последние операции'}</h2><span class="muted" style="font-size:12px">Май 2028</span></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Дата</th><th>Назначение</th><th>Сумма</th><th>Статус</th></tr></thead><tbody>${allLedger().slice(0,tab==='ledger'?50:5).map(r=>`<tr><td class="muted mono">${r.date.slice(8)}.${r.date.slice(5,7)}</td><td>${esc(r.label)}</td><td class="mono ${r.amount>0?'positive':''}">${r.amount>0?'+':'−'}${ctx.money(Math.abs(r.amount))}</td><td><span class="chip green">Проведено</span></td></tr>`).join('')}</tbody></table></div></section>`}function offer(){const signed=state.sponsors.includes('HELIX');ctx.modal({title:'HELIX · предложение партнёра',body:`<span class="chip amber">${signed?'Контракт уже подписан':'Новое предложение'}</span><div class="management-wordmark" style="margin-top:20px">HELIX</div><p class="muted">Партнёр в области программного обеспечения.</p><div class="management-modal-stats"><span>За сезон<strong>€2,4 млн</strong></span><span>Аванс<strong>€1,2 млн</strong></span><span>Срок<strong>2 сезона</strong></span><span>Зона<strong>Кожух двигателя</strong></span></div><div class="modal-callout">После подписания аванс поступит в общий резерв. Условие: логотип на кожухе двигателя.</div>`,footer:`<button class="btn" data-modal-close>Закрыть</button><button class="btn btn-primary" id="accept-sponsor" ${signed?'disabled':''}>Подписать контракт</button>`,onMount:el=>el.querySelector('#accept-sponsor').onclick=()=>{if(transact(ctx,1.2,'HELIX · аванс по контракту')){ctx.setState({sponsors:[...state.sponsors,'HELIX']});close(ctx);render();ctx.toast('Контракт HELIX подписан. Получен аванс €1,2 млн.')}}})}render();return()=>{}}

export function mountOrganization(container,ctx){const {state,icon}=ctx;let tab='programs';const programs=[{id:'formula',name:'VANTA Racing',series:'Formula World Championship',rank:'04',points:72,director:'Марк Беннетт',color:'#c83b4d',budget:76.2},{id:'gt',name:'VANTA GT',series:'GT World Series',rank:'06',points:38,director:'Софи Лоран',color:'#7c9fad',budget:24.6},{id:'endurance',name:'VANTA Endurance',series:'Endurance Cup',rank:'03',points:54,director:'Даниэль Коста',color:'#b7a06c',budget:11.2}];const render=()=>{container.innerHTML=`<div class="screen management-screen">${head('КАБИНЕТ ВЛАДЕЛЬЦА / VANTA GROUP','Организация','Три программы. Одна гоночная философия.',`<button class="btn" id="delegation">${icon('user-cog',15)} Полномочия</button><button class="btn btn-primary" id="allocate-budget">${icon('sliders-horizontal',15)} Распределить бюджет</button>`)}<div class="management-role-banner"><span class="management-role-icon">${icon('building-2',24)}</span><div><strong>Вы — владелец VANTA Group</strong><p>Назначайте руководителей и финансируйте программы. Гоночная тактика делегирована менеджерам.</p></div><span class="chip amber">ВЛАДЕЛЕЦ</span></div><div class="kpi-grid">${stat('Гоночные программы','03','Формула · GT · Выносливость',icon('flag',15))}${stat('Общий резерв',ctx.money(state.balance),'Доступно для инвестиций',icon('wallet',15))}${stat('Стоимость группы','€284 млн','+12,8% к прошлому сезону',icon('chart-no-axes-combined',15))}${stat('Доверие партнёров','88<span class="dim" style="font-size:15px"> /100</span>','Долгосрочные отношения',icon('handshake',15))}</div><div class="tabs management-tabs"><button class="tab ${tab==='programs'?'active':''}" data-otab="programs">Гоночные программы</button><button class="tab ${tab==='facilities'?'active':''}" data-otab="facilities">Инфраструктура</button><button class="tab ${tab==='board'?'active':''}" data-otab="board">Цели и руководители</button></div>${tab==='programs'?`<div class="management-program-grid">${programs.map(p=>`<article class="panel management-program" style="--program-color:${p.color}"><div class="management-program-top"><span class="management-program-glyph">${icon(p.id==='formula'?'flag':p.id==='gt'?'car-front':'timer',28)}</span><span class="chip">2028</span></div><span class="eyebrow">${p.series}</span><h2>${p.name}</h2><div class="management-program-rank"><strong>${p.rank}</strong><span>место<br><b>${p.points} очков</b></span></div><div class="management-program-details"><div><span>Руководитель</span><strong>${p.director}</strong></div><div><span>Бюджет программы</span><strong>${Math.round(112*state.allocations[p.id]/100*10)/10} млн €</strong></div><div><span>Доля финансирования</span><strong>${state.allocations[p.id]}%</strong></div></div>${progress(state.allocations[p.id])}<button class="btn btn-full" data-program="${p.id}">Открыть программу</button></article>`).join('')}</div><section class="panel management-owner-message"><div class="panel-body"><div class="eyebrow">НА РАССМОТРЕНИИ</div><h2>Команде нужен новый симулятор</h2><p>Марк Беннетт запрашивает €4,2 млн на обновление симулятора. Это улучшит подготовку молодых пилотов и работу с настройками.</p><button class="btn btn-primary" id="owner-invest">Рассмотреть инвестицию</button></div><div class="management-investment-number">€4,2<span>млн / инвестиция</span></div></section>`:tab==='facilities'?`<div class="management-facility-grid">${[['tunnel','Аэродинамическая труба','4 / 5',6.5,91,'wind'],['simulator','Гоночный симулятор','3 / 5',4.2,72,'monitor'],['factory','Производственный комплекс','3 / 5',5.8,76,'factory'],['academy','База академии','2 / 5',2.1,55,'graduation-cap']].map(([id,n,level,cost,load,ic])=>`<article class="panel management-facility"><span class="management-facility-icon">${icon(ic,32)}</span><div class="management-facility-heading"><h2>${n}</h2><span class="chip">${state.facilityLevels?.[id]?state.facilityLevels[id]+' / 5':level}</span></div><p class="muted">${state.projects.some(p=>p.id==='facility-'+id&&!p.installed)?'Модернизация начата':state.facilityLevels?.[id]?'Модернизация завершена':'Готовность к работе · высокая'}</p><div class="management-facility-load"><span>Загрузка</span><b>${load}%</b></div>${progress(load)}<button class="btn btn-full" data-invest="${id}" data-invest-name="${n}" data-invest-cost="${cost}" ${state.projects.some(p=>p.id==='facility-'+id)?'disabled':''}>Улучшить · €${String(cost).replace('.',',')} млн</button></article>`).join('')}</div>`:`<section class="panel"><header class="panel-head"><h2>Задачи руководителей программ</h2><span class="chip">Сезон 2028</span></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Руководитель</th><th>Программа</th><th>Цель</th><th>Доверие</th><th>Статус</th></tr></thead><tbody>${programs.map((p,i)=>`<tr><td><strong>${p.director}</strong></td><td>${p.name}</td><td>${['Топ-4 конструкторов','Топ-6 команд','Подиум в чемпионате'][i]}</td><td class="mono">${[82,76,88][i]}/100</td><td><span class="chip green">По плану</span></td></tr>`).join('')}</tbody></table></div></section><div class="management-finance-callout">${icon('user-check',22)}<div><strong>Управление через цели и полномочия</strong><p>Менеджеры отвечают за состав и стратегию. Вы утверждаете бюджет, крупные вложения и ограничения на контракты.</p></div></div>`}</div>`;container.querySelectorAll('[data-otab]').forEach(b=>b.onclick=()=>{tab=b.dataset.otab;render()});container.querySelector('#allocate-budget').onclick=budget;container.querySelector('#delegation').onclick=delegate;container.querySelectorAll('[data-program]').forEach(b=>b.onclick=()=>{ctx.setState({discipline:b.dataset.program});ctx.navigate('world')});container.querySelector('#owner-invest')?.addEventListener('click',()=>invest('simulator','Гоночный симулятор',4.2));container.querySelectorAll('[data-invest]').forEach(b=>b.onclick=()=>invest(b.dataset.invest,b.dataset.investName,+b.dataset.investCost))};function budget(){ctx.modal({title:'Распределение финансирования',body:`<p class="muted">Годовой бюджет группы — €112 млн. Сумма долей должна составлять 100%.</p>${programs.map(p=>`<div class="field" style="margin-top:18px"><label for="budget-${p.id}">${p.name}</label><input type="number" min="0" max="100" id="budget-${p.id}" value="${state.allocations[p.id]}"></div>`).join('')}<p id="allocation-total" class="muted"></p>`,footer:'<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" id="save-allocation">Утвердить бюджет</button>',onMount:el=>{const update=()=>{const sum=programs.reduce((n,p)=>n+(+el.querySelector('#budget-'+p.id).value||0),0);el.querySelector('#allocation-total').textContent='Итого: '+sum+'%';el.querySelector('#allocation-total').className=sum===100?'positive':'negative';el.querySelector('#save-allocation').disabled=sum!==100||programs.some(p=>+el.querySelector('#budget-'+p.id).value<0)};el.querySelectorAll('input').forEach(i=>i.oninput=update);update();el.querySelector('#save-allocation').onclick=()=>{const a={};programs.forEach(p=>a[p.id]=+el.querySelector('#budget-'+p.id).value);ctx.setState({allocations:a});close(ctx);render();ctx.toast('Бюджеты трёх программ обновлены.')}}})}function invest(id,name,cost){const exists=state.projects.some(p=>p.id==='facility-'+id);ctx.modal({title:'Инвестиция: '+name,body:`<p>Модернизация займёт 21 день и повысит пропускную способность подразделения.</p><div class="management-modal-stats"><span>Стоимость<strong>${ctx.money(cost)}</strong></span><span>Доступный резерв<strong>${ctx.money(state.balance)}</strong></span></div><div class="modal-callout">${exists?'Модернизация уже запущена. Статус доступен в разработках.':'Стоимость спишется сразу. Новый проект появится в техническом центре.'}</div>`,footer:`<button class="btn" data-modal-close>Закрыть</button><button class="btn btn-primary" id="approve-investment" ${exists?'disabled':''}>Утвердить инвестицию</button>`,onMount:el=>el.querySelector('#approve-investment').onclick=()=>{if(!transact(ctx,-cost,name+' · модернизация'))return;ctx.setState({projects:[...state.projects,{id:'facility-'+id,name,category:'Инфраструктура',progress:0,days:21,engineers:8,gain:'+1 уровень',cost}]});close(ctx);render();ctx.toast('Инвестиция утверждена. Модернизация запущена.')}})}function delegate(){const powers=state.delegation||{contracts:true,strategy:true,development:true};ctx.modal({title:'Полномочия руководителей',body:`<p class="muted">Настройте, какие решения менеджеры принимают самостоятельно.</p>${[['contracts','Контракты пилотов','В пределах утверждённого бюджета'],['strategy','Гоночная стратегия','Темп, пит-стопы и командные приказы'],['development','Проекты разработки','До €3 млн без отдельного согласования']].map(([k,t,s])=>`<div class="toggle-row"><div><strong>${t}</strong><small>${s}</small></div><input class="toggle" type="checkbox" data-power="${k}" aria-label="${t}" ${powers[k]?'checked':''}></div>`).join('')}`,footer:'<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" id="save-powers">Сохранить полномочия</button>',onMount:el=>el.querySelector('#save-powers').onclick=()=>{const p={};el.querySelectorAll('[data-power]').forEach(i=>p[i.dataset.power]=i.checked);ctx.setState({delegation:p});close(ctx);ctx.toast('Полномочия руководителей сохранены.')}})}render();return()=>{}}

export function mountProduction(container,ctx){const {state,icon}=ctx;let tab='products';const products=[{id:'vp6',name:'VP6 Hybrid',type:'СИЛОВАЯ УСТАНОВКА',sub:'Formula World · сезон 2028',power:91,reliability:84,efficiency:88,price:14.5,icon:'zap'},{id:'gt8',name:'GT8 Sequential',type:'КОРОБКА ПЕРЕДАЧ',sub:'Формула / GT · 8 ступеней',power:86,reliability:92,efficiency:90,price:2.4,icon:'cog'}];const render=()=>{const orders=state.orders||[];container.innerHTML=`<div class="screen management-screen">${head('ИНЖЕНЕРНАЯ КОМПАНИЯ / VANTA POWERTRAIN','Производство','Создавайте технику, с которой выигрывают ваши клиенты.',`<button class="btn" id="capacity-plan">${icon('sliders-horizontal',15)} Мощности</button><button class="btn btn-primary" id="new-product">${icon('plus',15)} Разработать изделие</button>`)}<div class="management-role-banner"><span class="management-role-icon">${icon('factory',24)}</span><div><strong>Вы — производитель двигателей и коробок передач</strong><p>Результат измеряется эффективностью изделий, надёжностью поставок и успехом клиентов.</p></div><span class="chip blue">ПРОИЗВОДИТЕЛЬ</span></div><div class="kpi-grid">${stat('Клиентские команды','04','В трёх дисциплинах',icon('handshake',15))}${stat('Загрузка производства',state.productionLoad+'%','Свободный резерв · '+(100-state.productionLoad)+'%',icon('factory',15))}${stat('Портфель заказов',ctx.money(32.8+orders.length*1.2),'Подтверждённые контракты',icon('clipboard-list',15))}${stat('Надёжность поставок','98,4%','Выполнено в срок',icon('shield-check',15))}</div><div class="tabs management-tabs"><button class="tab ${tab==='products'?'active':''}" data-ptab="products">Линейка изделий</button><button class="tab ${tab==='orders'?'active':''}" data-ptab="orders">Заказы <span class="chip">${orders.length+3}</span></button><button class="tab ${tab==='clients'?'active':''}" data-ptab="clients">Клиентские команды</button></div>${tab==='products'?`<div class="management-product-grid">${products.map(p=>`<article class="panel management-product"><div class="management-product-visual">${icon(p.icon,110)}<span>${p.id.toUpperCase()}</span><div class="management-spec-grid"></div></div><div class="management-product-body"><div class="eyebrow">${p.type}</div><h2>${p.name}</h2><p class="muted">${p.sub}</p><div class="management-product-stats">${[['Эффективность',p.power],['Надёжность',p.reliability],['Экономичность',p.efficiency]].map(([l,v])=>`<div><span>${l}</span><strong>${v}<small>/100</small></strong>${progress(v)}</div>`).join('')}</div><div class="management-product-price"><span>Сезонная поставка<strong>${ctx.money(state.productPrices?.[p.id]??p.price)}</strong></span><button class="btn" data-product="${p.id}">Параметры</button></div></div></article>`).join('')}</div><section class="panel management-order-offer"><div><span class="chip amber">Новый запрос</span><h2>ATLAS Motorsport ищет поставщика GT8</h2><p>Поставка 6 коробок передач и обслуживание в сезоне 2028. Аванс — €420 000.</p></div><button class="btn btn-primary" id="review-order">Рассмотреть заказ</button></section>`:tab==='orders'?`<section class="panel"><header class="panel-head"><h2>Производственный план</h2><span class="chip">Май 2028</span></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Заказ</th><th>Клиент</th><th>Изделие</th><th>Количество</th><th>Срок</th><th>Статус</th><th></th></tr></thead><tbody>${[...orders,{id:'VP6-026',client:'VANTA Racing',product:'VP6 Hybrid',qty:4,due:'22 мая',status:'Сборка'},{id:'GT8-043',client:'NORTHSTAR GT',product:'GT8 Sequential',qty:8,due:'24 мая',status:'Контроль качества'},{id:'VP6-025',client:'TITAN GP',product:'VP6 Hybrid',qty:4,due:'17 мая',status:'Отгружен'}].map(o=>`<tr><td class="mono">${o.id}</td><td>${o.client}</td><td>${o.product}</td><td>${o.qty}</td><td>${o.due}</td><td><span class="chip ${o.status==='Отгружен'?'green':o.status==='Сборка'?'amber':''}">${o.status}</span></td><td>${orders.includes(o)&&o.status!=='Отгружен'?`<button class="btn btn-sm" data-ship="${o.id}">Завершить заказ</button>`:''}</td></tr>`).join('')}</tbody></table></div></section><p class="prototype-note" style="margin-top:16px">В эталоне можно вручную завершить принятый заказ, чтобы проверить состояние поставки и расчёт.</p>`:`<section class="panel"><header class="panel-head"><h2>Результаты клиентов</h2><span class="chip">Сезон 2028</span></header><div class="table-wrap"><table class="data-table"><thead><tr><th>Команда</th><th>Серия</th><th>Поставка</th><th>Место</th><th>Отказы</th><th>Отношения</th></tr></thead><tbody>${[['VANTA Racing','Formula World','VP6 / GT8',4,0,96],['TITAN GP','Formula World','VP6',5,1,83],['NORTHSTAR GT','GT World Series','GT8',3,0,91],['RAVEN Endurance','Endurance Cup','GT8',7,0,88]].map(([n,s,p,r,f,rel])=>`<tr><td><strong>${n}</strong></td><td>${s}</td><td>${p}</td><td class="mono">${r}</td><td>${f}</td><td><span class="positive">${rel}/100</span></td></tr>`).join('')}</tbody></table></div></section><div class="management-finance-callout">${icon('radio-tower',24)}<div><strong>Смотрите технику в деле</strong><p>В гоночном центре производитель наблюдает за клиентами. Управление темпом и стратегией остаётся у команд.</p></div><button class="btn" data-route="race">Наблюдать гонку</button></div>`}</div>`;container.querySelectorAll('[data-ptab]').forEach(b=>b.onclick=()=>{tab=b.dataset.ptab;render()});container.querySelector('#capacity-plan').onclick=capacity;container.querySelector('#new-product').onclick=()=>{ctx.navigate('development');ctx.toast('В техническом центре можно начать разработку коробки GT8 Evo.')};container.querySelector('#review-order')?.addEventListener('click',order);container.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>product(b.dataset.product));container.querySelectorAll('[data-ship]').forEach(b=>b.onclick=()=>{const o=state.orders.find(o=>o.id===b.dataset.ship);ctx.setState({orders:state.orders.map(x=>x.id===o.id?{...x,status:'Отгружен'}:x),productionLoad:Math.max(0,state.productionLoad-8)});transact(ctx,.78,'ATLAS Motorsport · окончательный расчёт');render();ctx.toast('Заказ отгружен. Получен остаток €780 000.')})};function order(){const accepted=state.orders.some(o=>o.client==='ATLAS Motorsport');ctx.modal({title:'Заказ ATLAS Motorsport',body:`<p class="muted">GT World Series · клиентская программа</p><div class="management-modal-stats"><span>Изделие<strong>GT8 Sequential</strong></span><span>Количество<strong>6 коробок</strong></span><span>Стоимость заказа<strong>€1,2 млн</strong></span><span>Срок<strong>31 мая 2028</strong></span></div><div class="modal-callout">Аванс: €420 000. Загрузка производства увеличится на 8 процентных пунктов. ${accepted?'Заказ уже принят.':''}</div>`,footer:`<button class="btn" data-modal-close>Закрыть</button><button class="btn btn-primary" id="accept-order" ${accepted||state.productionLoad>92?'disabled':''}>Принять заказ</button>`,onMount:el=>el.querySelector('#accept-order').onclick=()=>{ctx.setState({orders:[...state.orders,{id:'GT8-044',client:'ATLAS Motorsport',product:'GT8 Sequential',qty:6,due:'31 мая',status:'Сборка'}],productionLoad:state.productionLoad+8});transact(ctx,.42,'ATLAS Motorsport · аванс за GT8');close(ctx);tab='orders';render();ctx.toast('Заказ принят. Аванс поступил на счёт.')}})}function product(id){const p=products.find(p=>p.id===id);ctx.modal({title:p.name+' · условия поставки',body:`<div class="field"><label for="product-price">Цена сезонного пакета, млн €</label><input type="number" id="product-price" min="1" max="30" step="0.1" value="${state.productPrices?.[id]??p.price}"></div><div class="field"><label for="product-support">Техническая поддержка</label><select id="product-support"><option>Стандартная</option> <option>Инженер на каждый этап</option><option>Расширенная заводская поддержка</option></select></div><p class="muted">Изменение применяется к новым предложениям. Подписанные контракты сохраняют свои условия.</p>`,footer:'<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" id="save-product">Обновить предложение</button>',onMount:el=>{if(state.productSupport?.[id])el.querySelector('#product-support').value=state.productSupport[id];el.querySelector('#save-product').onclick=()=>{const value=+el.querySelector('#product-price').value;if(!Number.isFinite(value)||value<1||value>30){ctx.toast('Укажите цену от €1 до €30 млн.');return}ctx.setState({productPrices:{...state.productPrices,[id]:value},productSupport:{...state.productSupport,[id]:el.querySelector('#product-support').value}});close(ctx);render();ctx.toast('Условия поставки обновлены.')}}})}function capacity(){ctx.modal({title:'План производства',body:`<div class="field"><label for="production-shifts">Рабочие смены</label><select id="production-shifts"><option value="1">Одна смена · базовые расходы</option><option value="2" selected>Две смены · штатный режим</option><option value="3">Три смены · +€0,3 млн за период</option></select></div><p class="muted">Дополнительная смена снижает текущую загрузку на 12 п.п. и помогает принять срочный заказ.</p>`,footer:'<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" id="save-capacity">Применить план</button>',onMount:el=>{el.querySelector('select').value=state.shifts||'2';el.querySelector('#save-capacity').onclick=()=>{const shifts=el.querySelector('select').value;if(shifts==='3'&&state.shifts!=='3'&&!transact(ctx,-.3,'Дополнительная производственная смена'))return;const old=Number(state.shifts||2);ctx.setState({shifts,productionLoad:Math.max(10,Math.min(100,state.productionLoad+(old-Number(shifts))*12))});close(ctx);render();ctx.toast('Производственный план обновлён.')}}})}render();return()=>{}}
